from lib import *
S = SS('f150')
R = J('f150'); rt = R['rtt']; idl = R['idle']; k = list(idl); i25, i1 = idl[k[0]], idl[k[1]]
steps = [
    step("nginx 有没有转发 WebSocket 升级头:没有配置 Upgrade 时,只允许 websocket 传输的客户端连接失败(ConnectionError);默认的客户端(先 polling 再升级)连接「成功」,但传输方式一直是 polling——悄悄退化成了长轮询,功能正常、性能与资源占用却变了。配置了 proxy_http_version 1.1、proxy_set_header Upgrade $http_upgrade、proxy_set_header Connection upgrade 之后,两种客户端都升级成 websocket。检查线上是否真的在用 WebSocket,要看实际的传输方式,不能只看「能连上」。", t=tl(S(1)), mark=lidx(S(1), '没有配置 Upgrade'), done=lidx(S(1), '配置了 proxy_http_version'), kv=KV([['缺 Upgrade 头', 'websocket 失败,默认客户端悄悄退化为 polling'], ['配置后', '升级为 websocket']], ['缺 Upgrade 头'])),
    step(f"nginx 的 proxy_read_timeout 会掐断空闲的 WebSocket(演示设成 3 秒):Socket.IO 默认 ping_interval=25 秒,连接在约 {i25[1]} 秒时被断开({i25[0]} = 空闲 7 秒后客户端已不在线),服务端日志里是 disconnect reason=transport close;把 ping_interval 设成 1 秒(比 proxy_read_timeout 短),连接空闲 7 秒仍然保持({i1[0]})。生产里 nginx 默认是 60 秒,Socket.IO 默认 25 秒的心跳刚好够;改了其中一个要检查另一个。", b=bars([['ping 25 秒:断开时间', i25[1], f'{i25[1]} s'], ['ping 1 秒:持续时间', i1[1], f'{i1[1]} s(仍在线)']], 8, mark=[0], done=[1]), t=tl(S(2)), mark=lidx(S(2), 'ping_interval=25'), done=lidx(S(2), 'ping_interval=1'), kv=KV([['ping 间隔 > 代理超时', '空闲连接被代理断开'], ['ping 间隔 < 代理超时', '连接保持']], ['ping 间隔 < 代理超时'])),
    step(f"经过 nginx 的 echo 往返(200 次):websocket 中位数 {rt['websocket'][0]:.2f} ms、p95 {rt['websocket'][1]:.2f} ms;polling 中位数 {rt['polling'][0]:.2f} ms、p95 {rt['polling'][1]:.2f} ms,约 {rt['polling'][0] / rt['websocket'][0]:.1f} 倍(本机、不含真实网络延迟)。", b=bars([['websocket', rt['websocket'][0], f"{rt['websocket'][0]:.2f} ms"], ['polling', rt['polling'][0], f"{rt['polling'][0]:.2f} ms"]], rt['polling'][0], mark=[1], done=[0]), t=tl(S(3)), done=lidx(S(3), 'websocket'), mark=lidx(S(3), 'polling'), kv=KV([['websocket', f"{rt['websocket'][0]:.2f} ms"], ['polling', f"{rt['polling'][0]:.2f} ms"]], ['websocket'])),
]
A = mkartf('f150', 150, 'Flask,WebSocket,Flask-SocketIO,nginx,真实验证,动画演示',
    f'实测 WebSocket 经过 nginx:缺少 Upgrade 头时 websocket-only 客户端连接失败、默认客户端悄悄退化为 polling;proxy_read_timeout 3 秒时默认 ping_interval=25 的连接在约 {i25[1]} 秒被断开而 ping_interval=1 保持;websocket 往返 {rt["websocket"][0]:.2f} ms 对 polling {rt["polling"][0]:.2f} ms。',
    'Flask-SocketIO 放在 nginx 后面要配什么?没配会怎样?空闲连接会不会被代理掐掉?WebSocket 比 polling 快多少?这篇用真实的 nginx 与 python-socketio 客户端,把答案量出来(基本的握手与房间见第 78 篇)。',
    [('polling', '缺少 Upgrade 头时默认客户端实际使用的传输方式——连得上但悄悄退化'), (f'{i25[1]} 秒', 'proxy_read_timeout 3 秒、ping_interval 25 秒时连接被断开的时间'), (f'{rt["polling"][0] / rt["websocket"][0]:.1f} 倍', '经过 nginx 时 polling 相对 websocket 的往返耗时')],
    [('Upgrade 头', '<p>上一篇:<a href="flask-server-sent-events.html">Server-Sent Events</a>;下一篇:<a href="flask-test-client.html">Flask Test Client</a>。</p><p>nginx 是自己起的实例(自签证书)。我第一次测试时给客户端写了自定义的 Host 头,结果 websocket 连接一直失败,去掉后才正常——那是我的测试写法的问题,不是 nginx 的行为。</p>'), ('proxy_read_timeout 与心跳', None), ('往返延迟', None)],
    steps, [ENV_F + '。Flask-SocketIO 5.6.1、python-socketio 5.17.0、nginx 1.31.6(自己的配置、非默认端口)', '没有验证:多 worker 下的消息队列与粘性会话(第 78 篇看过无 nginx 的情形)、wss 在真实证书下的握手、浏览器端 socket.io-client、负载均衡器的空闲超时、大量连接下 nginx 的 worker_connections'], 'WebSocket 与 Flask-SocketIO')
